'use client';
import React, { useState } from 'react';
import { API_BASE } from '../../../lib/env';
import { Search, CheckCircle, XCircle, FileText, Shield, ExternalLink, Loader2 } from 'lucide-react';

interface VerificationResult {
  valid: boolean;
  diploma?: {
    id: string;
    ediplomaId: string;
    solanaMint?: string;
    besuTxHash?: string;
    status: string;
    publicData?: {
      studentName?: string;
      studentIIN?: string;
      degree?: string;
      specialty?: string;
      graduationDate?: string;
      diplomaNumber?: string;
      university?: string;
    };
    issuedAt?: string;
  };
  message: string;
}

export default function VerifyPage() {
  const [searchType, setSearchType] = useState<'ediplomaId' | 'solanaMint'>('ediplomaId');
  const [searchValue, setSearchValue] = useState('');
  const [studentIIN, setStudentIIN] = useState('');
  const [studentName, setStudentName] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<VerificationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchValue.trim()) {
      setError('Пожалуйста, введите ID диплома или Solana mint адрес');
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      let url = '';
      if (searchType === 'ediplomaId') {
        url = `${API_BASE}/api/diplomas/verify/${encodeURIComponent(searchValue)}`;
        if (studentIIN) url += `?studentIIN=${encodeURIComponent(studentIIN)}`;
        if (studentName) url += `${studentIIN ? '&' : '?'}studentName=${encodeURIComponent(studentName)}`;
      } else {
        // Поиск по Solana mint
        const mintResponse = await fetch(`${API_BASE}/api/diplomas/solana/${encodeURIComponent(searchValue)}`);
        const mintData = await mintResponse.json();
        
        if (!mintData.found || !mintData.diploma) {
          setResult({
            valid: false,
            message: 'Диплом не найден в блокчейне',
          });
          setLoading(false);
          return;
        }

        // Верифицируем найденный диплом
        url = `${API_BASE}/api/diplomas/verify/${encodeURIComponent(mintData.diploma.ediplomaId)}`;
        if (studentIIN) url += `?studentIIN=${encodeURIComponent(studentIIN)}`;
        if (studentName) url += `${studentIIN ? '&' : '?'}studentName=${encodeURIComponent(studentName)}`;
      }

      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data: VerificationResult = await response.json();
      setResult(data);
    } catch (err: any) {
      setError(err.message || 'Ошибка при верификации диплома');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="text-center">
        <h1 className="text-5xl font-bold bg-gradient-to-r from-blue-400 via-green-400 to-purple-400 bg-clip-text text-transparent mb-4">
          Верификация Дипломов
        </h1>
        <p className="text-gray-400 text-lg max-w-2xl mx-auto">
          Проверьте подлинность диплома в блокчейне KazSmartChain
          <br />
          <span className="text-sm">Дипломдардың шынайылығын тексеру</span>
        </p>
      </div>

      {/* Search Form */}
      <div className="max-w-3xl mx-auto">
        <div className="p-6 rounded-xl border border-gray-800/50 glass bg-gradient-to-br from-gray-900/80 to-gray-900/40">
          <form onSubmit={handleVerify} className="space-y-4">
            {/* Search Type Selector */}
            <div className="flex gap-2 mb-4">
              <button
                type="button"
                onClick={() => {
                  setSearchType('ediplomaId');
                  setSearchValue('');
                  setResult(null);
                  setError(null);
                }}
                className={`flex-1 px-4 py-2 rounded-lg font-medium transition-all ${
                  searchType === 'ediplomaId'
                    ? 'bg-blue-500/20 text-blue-400 border border-blue-500/30'
                    : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:bg-gray-800'
                }`}
              >
                ID из app.ediploma.kz
              </button>
              <button
                type="button"
                onClick={() => {
                  setSearchType('solanaMint');
                  setSearchValue('');
                  setResult(null);
                  setError(null);
                }}
                className={`flex-1 px-4 py-2 rounded-lg font-medium transition-all ${
                  searchType === 'solanaMint'
                    ? 'bg-purple-500/20 text-purple-400 border border-purple-500/30'
                    : 'bg-gray-800/50 text-gray-400 border border-gray-700 hover:bg-gray-800'
                }`}
              >
                Solana Mint адрес
              </button>
            </div>

            {/* Search Input */}
            <div>
              <label className="block text-sm font-medium text-gray-300 mb-2">
                {searchType === 'ediplomaId' ? 'ID диплома из app.ediploma.kz' : 'Solana Mint адрес'}
              </label>
              <input
                type="text"
                value={searchValue}
                onChange={(e) => setSearchValue(e.target.value)}
                placeholder={searchType === 'ediplomaId' ? 'Введите ID диплома...' : 'Введите Solana mint адрес...'}
                className="w-full px-4 py-3 rounded-lg border border-gray-700 bg-gray-800/50 text-gray-200 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50"
                required
              />
            </div>

            {/* Optional Verification Fields */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  ИИН студента (опционально)
                </label>
                <input
                  type="text"
                  value={studentIIN}
                  onChange={(e) => setStudentIIN(e.target.value)}
                  placeholder="123456789012"
                  className="w-full px-4 py-3 rounded-lg border border-gray-700 bg-gray-800/50 text-gray-200 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Имя студента (опционально)
                </label>
                <input
                  type="text"
                  value={studentName}
                  onChange={(e) => setStudentName(e.target.value)}
                  placeholder="Иванов Иван Иванович"
                  className="w-full px-4 py-3 rounded-lg border border-gray-700 bg-gray-800/50 text-gray-200 placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50"
                />
              </div>
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={loading || !searchValue.trim()}
              className="w-full px-6 py-4 rounded-lg bg-gradient-to-r from-blue-600 to-green-500 text-white font-medium hover:from-blue-500 hover:to-green-400 disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center gap-2"
            >
              {loading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  <span>Проверка...</span>
                </>
              ) : (
                <>
                  <Search className="w-5 h-5" />
                  <span>Проверить диплом</span>
                </>
              )}
            </button>
          </form>
        </div>
      </div>

      {/* Error Message */}
      {error && (
        <div className="max-w-3xl mx-auto p-4 rounded-xl border border-red-500/20 bg-red-500/10 text-red-400">
          <div className="flex items-center gap-2">
            <XCircle className="w-5 h-5" />
            <span>{error}</span>
          </div>
        </div>
      )}

      {/* Verification Result */}
      {result && (
        <div className="max-w-3xl mx-auto">
          {result.valid ? (
            <div className="p-6 rounded-xl border border-green-500/20 bg-green-500/10">
              <div className="flex items-start gap-4">
                <div className="p-3 rounded-lg bg-green-500/20 text-green-400">
                  <CheckCircle className="w-8 h-8" />
                </div>
                <div className="flex-1">
                  <h2 className="text-2xl font-bold text-green-400 mb-2">Диплом верифицирован</h2>
                  <p className="text-green-300 mb-4">{result.message}</p>

                  {result.diploma && (
                    <div className="mt-4 space-y-3">
                      <div className="p-4 rounded-lg border border-gray-800/50 bg-gray-900/50">
                        <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
                          <FileText className="w-5 h-5" />
                          Информация о дипломе
                        </h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm">
                          {result.diploma.publicData?.studentName && (
                            <div>
                              <span className="text-gray-400">Студент:</span>
                              <span className="ml-2 text-white font-medium">{result.diploma.publicData.studentName}</span>
                            </div>
                          )}
                          {result.diploma.publicData?.studentIIN && (
                            <div>
                              <span className="text-gray-400">ИИН:</span>
                              <span className="ml-2 text-white font-mono">{result.diploma.publicData.studentIIN}</span>
                            </div>
                          )}
                          {result.diploma.publicData?.degree && (
                            <div>
                              <span className="text-gray-400">Степень:</span>
                              <span className="ml-2 text-white">{result.diploma.publicData.degree}</span>
                            </div>
                          )}
                          {result.diploma.publicData?.specialty && (
                            <div>
                              <span className="text-gray-400">Специальность:</span>
                              <span className="ml-2 text-white">{result.diploma.publicData.specialty}</span>
                            </div>
                          )}
                          {result.diploma.publicData?.university && (
                            <div>
                              <span className="text-gray-400">Университет:</span>
                              <span className="ml-2 text-white">{result.diploma.publicData.university}</span>
                            </div>
                          )}
                          {result.diploma.publicData?.graduationDate && (
                            <div>
                              <span className="text-gray-400">Дата выпуска:</span>
                              <span className="ml-2 text-white">{result.diploma.publicData.graduationDate}</span>
                            </div>
                          )}
                          {result.diploma.publicData?.diplomaNumber && (
                            <div>
                              <span className="text-gray-400">Номер диплома:</span>
                              <span className="ml-2 text-white font-mono">{result.diploma.publicData.diplomaNumber}</span>
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Blockchain Info */}
                      <div className="p-4 rounded-lg border border-gray-800/50 bg-gray-900/50">
                        <h3 className="text-lg font-semibold text-white mb-3 flex items-center gap-2">
                          <Shield className="w-5 h-5" />
                          Блокчейн информация
                        </h3>
                        <div className="space-y-2 text-sm">
                          {result.diploma.solanaMint && (
                            <div className="flex items-center justify-between">
                              <span className="text-gray-400">Solana NFT:</span>
                              <span className="text-white font-mono text-xs">{result.diploma.solanaMint}</span>
                            </div>
                          )}
                          {result.diploma.besuTxHash && (
                            <div className="flex items-center justify-between">
                              <span className="text-gray-400">Besu Transaction:</span>
                              <a
                                href={`/explorer/tx/${result.diploma.besuTxHash}`}
                                className="text-blue-400 hover:text-blue-300 font-mono text-xs flex items-center gap-1"
                              >
                                {result.diploma.besuTxHash.slice(0, 10)}...{result.diploma.besuTxHash.slice(-8)}
                                <ExternalLink className="w-3 h-3" />
                              </a>
                            </div>
                          )}
                          <div className="flex items-center justify-between">
                            <span className="text-gray-400">Статус:</span>
                            <span className={`px-2 py-1 rounded text-xs font-medium ${
                              result.diploma.status === 'issued'
                                ? 'bg-green-500/20 text-green-400'
                                : result.diploma.status === 'revoked'
                                ? 'bg-red-500/20 text-red-400'
                                : 'bg-blue-500/20 text-blue-400'
                            }`}>
                              {result.diploma.status === 'issued' ? 'Выпущен' : result.diploma.status === 'revoked' ? 'Отозван' : 'Обновлен'}
                            </span>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="p-6 rounded-xl border border-red-500/20 bg-red-500/10">
              <div className="flex items-start gap-4">
                <div className="p-3 rounded-lg bg-red-500/20 text-red-400">
                  <XCircle className="w-8 h-8" />
                </div>
                <div className="flex-1">
                  <h2 className="text-2xl font-bold text-red-400 mb-2">Диплом не верифицирован</h2>
                  <p className="text-red-300">{result.message}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

